import { Assets, type Spritesheet } from 'pixi.js'

// Runtime files generated by scripts/build-assets.ts into public/game/.
const BASE = `${import.meta.env.BASE_URL}game/`

export interface GameAssets {
  ships: Spritesheet
  tiles: Spritesheet
  ui: Spritesheet
}

/**
 * Picks the atlas density for the screen. Ships only exist at 1× — the
 * provided "retina" ships sheet is not a 2× image (see assets/README.md).
 */
export function atlasUrls(devicePixelRatio: number): Record<keyof GameAssets, string> {
  const suffix = devicePixelRatio > 1.25 ? '@2x' : ''
  return {
    ships: `${BASE}ships.json`,
    tiles: `${BASE}tiles${suffix}.json`,
    ui: `${BASE}ui${suffix}.json`,
  }
}

/**
 * Loads every texture combat needs, reporting progress in [0, 1].
 *
 * Rejects if any file fails. Calling it again retries only what failed:
 * PixiJS caches successful loads and drops failed ones from its cache, so a
 * retry never re-downloads what already arrived, and textures are shared by
 * every match.
 */
export async function loadGameAssets(
  onProgress: (progress: number) => void,
  devicePixelRatio = window.devicePixelRatio,
): Promise<GameAssets> {
  const urls = atlasUrls(devicePixelRatio)
  const loaded = await Assets.load<Spritesheet>(Object.values(urls), onProgress)
  return {
    ships: loaded[urls.ships] as Spritesheet,
    tiles: loaded[urls.tiles] as Spritesheet,
    ui: loaded[urls.ui] as Spritesheet,
  }
}
